<?php
declare(strict_types=1); namespace App; use PDO;
final class Auth { public function __construct(private PDO $db){} public function login(array $d):never{$email=strtolower(trim((string)($d['email']??'')));$pass=(string)($d['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$pass==='')Http::json(['error'=>'Credenciais inválidas'],422);$s=$this->db->prepare('SELECT id,name,email,phone,password_hash,role,status FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||$u['status']!=='active'||!password_verify($pass,$u['password_hash']))Http::json(['error'=>'E-mail ou palavra-passe incorrectos'],401);session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;Http::json(['user'=>$u]);} public function logout():never{$_SESSION=[];session_destroy();Http::json(['ok'=>true]);} }
